<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { asset, categories, categoryPaths, colors, swatches, imageColors, priceLabel, sizeLabel } from '../lib/catalog.js'
import { api, state, addToCart, savedItem, toggleWishlist, notify } from '../lib/store.js'
import Icon from '../components/Icon.vue'
import Notices from '../components/Notices.vue'
import NotFound from './NotFound.vue'
const route = useRoute(), router = useRouter(), product = ref(null), loading = ref(true), error = ref(''), notFound = ref(false), color = ref(''), size = ref(''), activeImage = ref(0), attempted = ref(false), busy = ref(false)
const available = computed(() => imageColors(product.value)), images = computed(() => product.value?.imagesByColor[color.value] || [])
onMounted(async () => { try { product.value = await api(`/products/${route.params.id}`); color.value = available.value.includes(route.query.farbe) ? route.query.farbe : available.value[0] || '' } catch (e) { if (e.status === 404) notFound.value = true; else error.value = e.message } finally { loading.value = false } })
watch(color, () => { activeImage.value = 0 })
watch(() => route.query.farbe, value => { if (available.value.includes(value)) color.value = value })
async function add() { attempted.value = true; if (!color.value || !size.value) return; busy.value = true; error.value = ''; try { await addToCart({ productId: product.value.id, color: color.value, size: size.value }) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function wish() { if (!state.user) return router.push('/login'); try { await toggleWishlist(product.value.id, color.value) } catch (e) { notify(e.message, true) } }
</script>
<template><NotFound v-if="notFound" /><section v-else class="page"><Notices :busy="loading" :error="error" /><template v-if="product"><div class="breadcrumb"><RouterLink to="/">Startseite</RouterLink><span>/</span><RouterLink :to="categoryPaths[product.category]">{{ categories[product.category] }}</RouterLink><span>/</span>{{ product.name }}</div><div class="product-detail"><div class="product-gallery"><div class="main-product-image"><img v-if="images.length" :src="asset(images[activeImage])" :alt="`${product.name} – ${colors[color]}, Ansicht ${activeImage + 1}`"></div><div v-if="images.length > 1" class="thumbnails"><button v-for="(image, index) in images" :key="image" :class="{ selected: index === activeImage }" :aria-label="`Ansicht ${index + 1} anzeigen`" :aria-pressed="index === activeImage" @click="activeImage = index"><img :src="asset(image)" alt=""></button></div></div><div class="product-information"><span class="eyebrow">{{ categories[product.category] }} · RAINBOW.DESIGN</span><h1>{{ product.name }}</h1><p class="large-price">{{ priceLabel(product, size) }}</p><p class="product-description">{{ product.description }}</p><fieldset><legend>Farbe <span class="muted">— {{ colors[color] }}</span></legend><div class="color-options"><button v-for="option in available" :key="option" class="color-swatch" :class="{ selected: color === option }" :style="{ '--swatch': swatches[option] }" :title="colors[option]" :aria-label="colors[option]" :aria-pressed="color === option" @click="color = option"><Icon v-if="color === option" name="check" /></button></div></fieldset><fieldset><legend>Größe</legend><div class="size-options"><button v-for="option in product.sizes" :key="option" :class="{ selected: size === option }" :aria-pressed="size === option" @click="size = option">{{ sizeLabel(option) }}</button></div><p v-if="attempted && !size" class="error-text" role="alert">Bitte wähle eine Größe aus.</p></fieldset><div class="product-add-row"><button class="button" :disabled="busy" @click="add">{{ busy ? 'Wird hinzugefügt …' : 'In den Warenkorb' }}<Icon name="bag" /></button><button class="icon-button bordered" :aria-label="savedItem(product.id, color) ? 'Aus Wunschliste entfernen' : 'Zur Wunschliste hinzufügen'" :aria-pressed="!!savedItem(product.id, color)" @click="wish"><Icon name="heart" :filled="!!savedItem(product.id, color)" /></button></div><div v-if="product.customizable" class="custom-callout"><span class="eyebrow">NOCH PERSÖNLICHER?</span><p>Mach diesen Mantel zu deinem Unikat.</p><RouterLink class="underlined-link" to="/dein-design">Dein Design <Icon name="arrow" /></RouterLink></div></div></div></template></section></template>
